package netcdf_test

// The fixtures in testdata are generated by netCDF-C 4.10.1's ncgen from the
// CDL files in testdata/cdl and verified by ncdump; see testdata/README.md.
// These tests read them through the public API and compare with the values the
// CDL declares, which is what ncdump prints.

import (
	"bytes"
	"errors"
	"math"
	"testing"

	"github.com/scigolib/netcdf"
)

func openFixture(t *testing.T, name string) *netcdf.File {
	t.Helper()
	f, err := netcdf.Open("testdata/" + name)
	if err != nil {
		t.Fatalf("Open(%s): %v", name, err)
	}
	t.Cleanup(func() {
		if err := f.Close(); err != nil {
			t.Errorf("Close: %v", err)
		}
	})
	return f
}

func mustVar(t *testing.T, f *netcdf.File, name string) *netcdf.Variable {
	t.Helper()
	v, ok := f.Variable(name)
	if !ok {
		t.Fatalf("variable %q not found", name)
	}
	return v
}

func readAll[T any](t *testing.T, f *netcdf.File, name string) []T {
	t.Helper()
	v := mustVar(t, f, name)
	out := make([]T, v.Len())
	if err := v.Read(&out); err != nil {
		t.Fatalf("Read(%q): %v", name, err)
	}
	return out
}

func wantSlice[T comparable](t *testing.T, what string, got, want []T) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: got %d values, want %d (%v)", what, len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: value %d = %v, want %v", what, i, got[i], want[i])
		}
	}
}

// attrOwner is satisfied by both *netcdf.File and *netcdf.Variable.
type attrOwner interface {
	Attribute(string) (*netcdf.Attribute, bool)
}

func wantAttrInts(t *testing.T, owner attrOwner, what, name string, want []int32) {
	t.Helper()
	a, ok := owner.Attribute(name)
	if !ok {
		t.Fatalf("%s:%s missing", what, name)
	}
	got, ok := a.Value().([]int32)
	if !ok {
		t.Fatalf("%s:%s = %T, want []int32", what, name, a.Value())
	}
	wantSlice(t, what+":"+name, got, want)
}

func wantAttrDoubles(t *testing.T, owner attrOwner, what, name string, want []float64) {
	t.Helper()
	a, ok := owner.Attribute(name)
	if !ok {
		t.Fatalf("%s:%s missing", what, name)
	}
	got, ok := a.Value().([]float64)
	if !ok {
		t.Fatalf("%s:%s = %T, want []float64", what, name, a.Value())
	}
	wantSlice(t, what+":"+name, got, want)
}

func TestSimpleAllFormats(t *testing.T) {
	formats := map[string]netcdf.Format{
		"simple-cdf1.nc": netcdf.FormatClassic,
		"simple-cdf2.nc": netcdf.FormatClassic64,
		"simple-cdf5.nc": netcdf.FormatClassic64Data,
	}
	for name, format := range formats {
		t.Run(name, func(t *testing.T) {
			f := openFixture(t, name)
			if f.Format() != format {
				t.Errorf("Format = %v, want %v", f.Format(), format)
			}
			checkSimpleMetadata(t, f)
			checkSimpleData(t, f)
		})
	}
}

func checkSimpleMetadata(t *testing.T, f *netcdf.File) {
	t.Helper()
	dims := f.Dimensions()
	if len(dims) != 2 || dims[0].Name() != "x" || dims[0].Len() != 4 ||
		dims[1].Name() != "y" || dims[1].Len() != 3 {
		t.Fatalf("dimensions = %v", dims)
	}
	if d, ok := f.Dimension("x"); !ok || d != dims[0] {
		t.Errorf("Dimension(x) = %v %v", d, ok)
	}
	if a, ok := f.Attribute("title"); !ok || a.String() != "simple fixture" {
		t.Errorf("title = %v %v", a, ok)
	}
	wantAttrInts(t, f, "global", "version", []int32{7})
	wantAttrDoubles(t, f, "global", "pi", []float64{3.14159})

	a := mustVar(t, f, "a")
	if a.Type() != netcdf.TypeFloat {
		t.Errorf("a.Type = %v", a.Type())
	}
	wantSlice(t, "a.Shape", a.Shape(), []int64{4, 3})
	if u, ok := a.Attribute("units"); !ok || u.String() != "m/s" {
		t.Errorf("a:units = %v %v", u, ok)
	}
	wantAttrDoubles(t, a, "a", "valid_max", []float64{100})

	b := mustVar(t, f, "b")
	if b.Type() != netcdf.TypeInt {
		t.Errorf("b.Type = %v", b.Type())
	}
	wantSlice(t, "b.Shape", b.Shape(), []int64{3})
	wantAttrInts(t, b, "b", "scale", []int32{2})
}

func checkSimpleData(t *testing.T, f *netcdf.File) {
	t.Helper()
	want := make([]float32, 12)
	for i := range want {
		want[i] = float32(i)
	}
	got := readAll[float32](t, f, "a")
	wantSlice(t, "a", got, want)
	wantSlice(t, "b", readAll[int32](t, f, "b"), []int32{10, 20, 30})
	// Every hyperslab of the 2-D variable: the review's repro class lives here.
	checkAllSelections(t, mustVar(t, f, "a"), got)
}

func TestTypesAllTypes(t *testing.T) {
	for _, name := range []string{"types-cdf1.nc", "types-cdf2.nc"} {
		t.Run(name, func(t *testing.T) {
			f := openFixture(t, name)
			wantSlice(t, "vb", readAll[int8](t, f, "vb"), []int8{-128, -1, 0, 1, 127})
			wantSlice(t, "vc", readAll[byte](t, f, "vc"), []byte("hello"))
			wantSlice(t, "vs", readAll[int16](t, f, "vs"), []int16{-32768, -1, 0, 1, 32767})
			wantSlice(t, "vi", readAll[int32](t, f, "vi"), []int32{math.MinInt32, -1, 0, 1, math.MaxInt32})
			wantSlice(t, "vf", readAll[float32](t, f, "vf"), []float32{-1.5, 0, 0.5, 1, 2.25})
			wantSlice(t, "vd", readAll[float64](t, f, "vd"), []float64{-1.5, 0, 0.5, 1, 2.25})
		})
	}
}

func TestRecordLayout(t *testing.T) {
	for _, name := range []string{"record-cdf1.nc", "record-cdf2.nc", "record-cdf5.nc"} {
		t.Run(name, func(t *testing.T) {
			checkRecordFile(t, openFixture(t, name))
		})
	}
}

func checkRecordFile(t *testing.T, f *netcdf.File) {
	t.Helper()
	if f.NumRecs() != 3 {
		t.Fatalf("NumRecs = %d, want 3", f.NumRecs())
	}
	timeDim, ok := f.Dimension("time")
	if !ok || !timeDim.Unlimited() || timeDim.Len() != 3 {
		t.Fatalf("time = %+v %v", timeDim, ok)
	}
	temp := mustVar(t, f, "temp")
	if !temp.Record() {
		t.Fatal("temp is not a record variable")
	}
	wantSlice(t, "temp.Shape", temp.Shape(), []int64{3, 2})
	wantSlice(t, "fixed", readAll[float64](t, f, "fixed"), []float64{1.5, 2.5})
	wantSlice(t, "temp", readAll[int32](t, f, "temp"), []int32{10, 11, 20, 21, 30, 31})
	wantSlice(t, "flag", readAll[int16](t, f, "flag"), []int16{1, 0, -1})

	// Hyperslabs across the record interleave.
	got := make([]int32, 4)
	if err := temp.ReadSlice(&got, []int64{1, 0}, []int64{2, 2}); err != nil {
		t.Fatalf("ReadSlice: %v", err)
	}
	wantSlice(t, "temp[1:3,0:2]", got, []int32{20, 21, 30, 31})

	got = make([]int32, 2)
	if err := temp.ReadSlice(&got, []int64{1, 1}, []int64{2, 1}); err != nil {
		t.Fatalf("ReadSlice column: %v", err)
	}
	wantSlice(t, "temp[1:3,1]", got, []int32{21, 31})

	flag := mustVar(t, f, "flag")
	gotFlag := make([]int16, 1)
	if err := flag.ReadSlice(&gotFlag, []int64{2}, []int64{1}); err != nil {
		t.Fatalf("ReadSlice flag: %v", err)
	}
	wantSlice(t, "flag[2]", gotFlag, []int16{-1})
}

func TestSingleRecordVariable(t *testing.T) {
	f := openFixture(t, "single_rec-cdf1.nc")
	if f.NumRecs() != 5 {
		t.Fatalf("NumRecs = %d, want 5", f.NumRecs())
	}
	wantSlice(t, "b", readAll[int8](t, f, "b"), []int8{7, -7, 0, 42, -42})

	b := mustVar(t, f, "b")
	got := make([]int8, 2)
	if err := b.ReadSlice(&got, []int64{3}, []int64{2}); err != nil {
		t.Fatalf("ReadSlice: %v", err)
	}
	wantSlice(t, "b[3:5]", got, []int8{42, -42})
}

func TestEmptyFile(t *testing.T) {
	f := openFixture(t, "empty-cdf1.nc")
	if f.Format() != netcdf.FormatClassic {
		t.Errorf("Format = %v", f.Format())
	}
	if f.NumRecs() != 0 || len(f.Dimensions()) != 0 || len(f.Variables()) != 0 || len(f.Attributes()) != 0 {
		t.Errorf("empty file has content: %+v", f)
	}
}

func TestAttributeTypes(t *testing.T) {
	f := openFixture(t, "attrs-cdf1.nc")
	v := mustVar(t, f, "v")
	if u, ok := v.Attribute("units"); !ok || u.String() != "count" {
		t.Errorf("v:units = %v %v", u, ok)
	}
	wantAttrInts(t, v, "v", "valid_range", []int32{0, 100})
	wantAttrDoubles(t, f, "global", "reals", []float64{1.5, -2.25})
	wantSlice(t, "v", readAll[int32](t, f, "v"), []int32{3, 4})
}

func TestReadErrors(t *testing.T) {
	f := openFixture(t, "simple-cdf1.nc")
	a := mustVar(t, f, "a")

	var wrong []float64
	if err := a.Read(&wrong); !errors.Is(err, netcdf.ErrTypeMismatch) {
		t.Errorf("Read into []float64 = %v, want ErrTypeMismatch", err)
	}
	short := make([]float32, 11)
	if err := a.Read(&short); !errors.Is(err, netcdf.ErrOutOfRange) {
		t.Errorf("Read into short slice = %v, want ErrOutOfRange", err)
	}
	over := make([]float32, 12)
	if err := a.ReadSlice(&over, []int64{3, 0}, []int64{2, 3}); !errors.Is(err, netcdf.ErrOutOfRange) {
		t.Errorf("ReadSlice past the edge = %v, want ErrOutOfRange", err)
	}
	neg := make([]float32, 3)
	if err := a.ReadSlice(&neg, []int64{0, -1}, []int64{1, 3}); !errors.Is(err, netcdf.ErrOutOfRange) {
		t.Errorf("ReadSlice with a negative start = %v, want ErrOutOfRange", err)
	}
	if err := a.Read(nil); err == nil {
		t.Error("Read(nil) returned no error")
	}
	empty := []float32{}
	if err := a.Read(&empty); err == nil {
		t.Error("Read into an empty slice returned no error")
	}
}

func TestClosedFile(t *testing.T) {
	f := openFixture(t, "simple-cdf1.nc")
	a := mustVar(t, f, "a")
	if err := f.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if err := f.Close(); err != nil {
		t.Errorf("second Close: %v", err)
	}
	out := make([]float32, 12)
	if err := a.Read(&out); !errors.Is(err, netcdf.ErrClosed) {
		t.Errorf("Read after Close = %v, want ErrClosed", err)
	}
}

// TestCorpusNullBytePadding reads a file from the netCDF-C test corpus
// (ncdump/ref_null_byte_padding_test.nc, v4.10.1): its header padding is not
// made of NUL bytes, and netCDF-C accepts it; so must we.
func TestCorpusNullBytePadding(t *testing.T) {
	f := openFixture(t, "null_byte_padding-cdf2.nc")
	checkPaddingHeader(t, f)
	checkPaddingData(t, f)
}

func checkPaddingHeader(t *testing.T, f *netcdf.File) {
	t.Helper()
	if f.Format() != netcdf.FormatClassic64 {
		t.Errorf("Format = %v, want CDF-2", f.Format())
	}
	if len(f.Dimensions()) != 0 || f.NumRecs() != 0 {
		t.Errorf("dims=%d numrecs=%d, want none", len(f.Dimensions()), f.NumRecs())
	}
	wantTypes := map[string]netcdf.Type{
		"raw_data_start_date": netcdf.TypeDouble,
		"subset_end_date":     netcdf.TypeInt,
		"globe":               netcdf.TypeDouble,
		"raw_data_end_date":   netcdf.TypeDouble,
		"subset_start_date":   netcdf.TypeInt,
	}
	vars := f.Variables()
	if len(vars) != len(wantTypes) {
		t.Fatalf("%d variables, want %d", len(vars), len(wantTypes))
	}
	for _, v := range vars {
		want, ok := wantTypes[v.Name()]
		if !ok {
			t.Fatalf("unexpected variable %q", v.Name())
		}
		if v.Type() != want || len(v.Shape()) != 0 {
			t.Errorf("%q: type %v shape %v, want scalar %v", v.Name(), v.Type(), v.Shape(), want)
		}
	}
	if a, ok := f.Attribute("coordinates"); !ok ||
		a.String() != "raw_data_start_date subset_end_date raw_data_end_date subset_start_date" {
		t.Errorf("coordinates = %v %v", a, ok)
	}
	raw := mustVar(t, f, "raw_data_start_date")
	wantAttrDoubles(t, raw, "raw_data_start_date", "_FillValue", []float64{1e20})
	globe := mustVar(t, f, "globe")
	a, ok := globe.Attribute("_FillValue")
	if !ok {
		t.Fatal("globe:_FillValue missing")
	}
	if v, ok := a.Value().([]float64); !ok || len(v) != 1 || !math.IsNaN(v[0]) {
		t.Errorf("globe:_FillValue = %v, want NaN", a.Value())
	}
}

func checkPaddingData(t *testing.T, f *netcdf.File) {
	t.Helper()
	start := make([]float64, 1)
	if err := mustVar(t, f, "raw_data_start_date").Read(&start); err != nil {
		t.Fatalf("Read: %v", err)
	}
	if start[0] != 1825 {
		t.Errorf("raw_data_start_date = %v, want 1825", start[0])
	}
	sub := make([]int32, 1)
	if err := mustVar(t, f, "subset_start_date").Read(&sub); err != nil {
		t.Fatalf("Read: %v", err)
	}
	if sub[0] != 0 {
		t.Errorf("subset_start_date = %v, want 0", sub[0])
	}
	// ncdump prints 17.1305600943611 (15 significant digits); the stored
	// double is 17.130560094361062.
	got := make([]float64, 1)
	if err := mustVar(t, f, "globe").Read(&got); err != nil {
		t.Fatalf("Read: %v", err)
	}
	if math.Abs(got[0]-17.1305600943611) > 1e-12 {
		t.Errorf("globe = %v, want 17.1305600943611", got[0])
	}
}

// TestCorpusBadCDF5Begin is the netCDF-C corpus file nc_test/bad_cdf5_begin.nc,
// which netCDF-C itself rejects as an unknown format: its starting offsets
// violate the section order.
func TestCorpusBadCDF5Begin(t *testing.T) {
	f, err := netcdf.Open("testdata/bad_cdf5_begin.nc")
	if err == nil {
		f.Close()
		t.Fatal("corrupt file was accepted")
	}
	if !errors.Is(err, netcdf.ErrCorrupt) {
		t.Errorf("error = %v, want ErrCorrupt", err)
	}
}

// TestLayoutFixtures reads the layout model in all three formats: a 3-D
// fixed variable and a byte record variable beside an int record variable
// (the padding path), then checks every possible hyperslab of both.
func TestLayoutFixtures(t *testing.T) {
	for _, name := range []string{"layout-cdf1.nc", "layout-cdf2.nc", "layout-cdf5.nc"} {
		t.Run(name, func(t *testing.T) {
			checkLayoutFile(t, openFixture(t, name))
		})
	}
}

func checkLayoutFile(t *testing.T, f *netcdf.File) {
	t.Helper()
	if f.NumRecs() != 5 {
		t.Fatalf("NumRecs = %d, want 5", f.NumRecs())
	}
	cube := mustVar(t, f, "cube")
	if cube.Record() {
		t.Fatal("cube is a record variable")
	}
	wantSlice(t, "cube.Shape", cube.Shape(), []int64{4, 2, 3})
	vals := make([]float32, 24)
	for i := range vals {
		vals[i] = float32(i)
	}
	wantSlice(t, "cube", readAll[float32](t, f, "cube"), vals)
	wantSlice(t, "b", readAll[int8](t, f, "b"), []int8{1, -1, 2, -2, 5})
	wantSlice(t, "temp", readAll[int32](t, f, "temp"),
		[]int32{10, 11, 12, 20, 21, 22, 30, 31, 32, 40, 41, 42, 50, 51, 52})

	// Every sub-slab must read exactly what a full read holds. This is the
	// guard against the run-coalescing class of bug: a wrong run offset still
	// yields the right number of values, so only a value comparison catches it.
	checkAllSelections(t, cube, vals)
	checkAllSelections(t, mustVar(t, f, "temp"), readAll[int32](t, f, "temp"))
}

// checkAllSelections tries every start/count combination of every dimension
// and compares ReadSlice with a naive gather from the full contents.
func checkAllSelections[T comparable](t *testing.T, v *netcdf.Variable, full []T) {
	t.Helper()
	shape := v.Shape()
	start := make([]int64, len(shape))
	count := make([]int64, len(shape))
	var walk func(dim int)
	walk = func(dim int) {
		if dim == len(shape) {
			got := make([]T, selectionLen(count))
			if err := v.ReadSlice(&got, start, count); err != nil {
				t.Fatalf("ReadSlice(%v, %v): %v", start, count, err)
			}
			want := gatherSelection(full, shape, start, count)
			if len(got) != len(want) {
				t.Fatalf("ReadSlice(%v, %v) returned %d values, want %d", start, count, len(got), len(want))
			}
			for i := range want {
				if got[i] != want[i] {
					t.Fatalf("ReadSlice(%v, %v)[%d] = %v, want %v", start, count, i, got[i], want[i])
				}
			}
			return
		}
		for s := int64(0); s <= shape[dim]; s++ {
			start[dim] = s
			for c := int64(0); c <= shape[dim]-s; c++ {
				count[dim] = c
				walk(dim + 1)
			}
		}
	}
	walk(0)
}

func selectionLen(count []int64) int64 {
	n := int64(1)
	for _, c := range count {
		n *= c
	}
	return n
}

// gatherSelection returns the values a hyperslab selects, by indexing the
// full row-major contents directly.
func gatherSelection[T any](full []T, shape, start, count []int64) []T {
	n := selectionLen(count)
	if n == 0 {
		return nil
	}
	strides := make([]int64, len(shape))
	acc := int64(1)
	for i := len(shape) - 1; i >= 0; i-- {
		strides[i] = acc
		acc *= shape[i]
	}
	out := make([]T, 0, n)
	idx := append([]int64(nil), start...)
	for {
		off := int64(0)
		for i := range idx {
			off += idx[i] * strides[i]
		}
		out = append(out, full[off])
		i := len(idx) - 1
		for ; i >= 0; i-- {
			idx[i]++
			if idx[i] < start[i]+count[i] {
				break
			}
			idx[i] = start[i]
		}
		if i < 0 {
			return out
		}
	}
}

func TestFormatDispatch(t *testing.T) {
	hdf5 := []byte{0x89, 'H', 'D', 'F', '\r', '\n', 0x1a, '\n', 0, 0, 0, 0}
	if _, err := netcdf.NewReader(bytes.NewReader(hdf5), int64(len(hdf5))); !errors.Is(err, netcdf.ErrUnsupportedFormat) {
		t.Errorf("NetCDF-4 file = %v, want ErrUnsupportedFormat", err)
	}
	junk := []byte("not a netcdf file at all")
	if _, err := netcdf.NewReader(bytes.NewReader(junk), int64(len(junk))); !errors.Is(err, netcdf.ErrNotNetCDF) {
		t.Errorf("junk = %v, want ErrNotNetCDF", err)
	}
	truncated := []byte("CDF\x01\x00\x00\x00")
	if _, err := netcdf.NewReader(bytes.NewReader(truncated), int64(len(truncated))); !errors.Is(err, netcdf.ErrCorrupt) {
		t.Errorf("truncated classic = %v, want ErrCorrupt", err)
	}
}
